const assert = require('assert');
const { parseArgs } = require('./args.js');

assert.deepStrictEqual(parseArgs(['--verbose', '--out=dist', 'input.txt']), {
  flags: ['verbose'],
  options: { out: 'dist' },
  positionals: ['input.txt'],
});

assert.deepStrictEqual(parseArgs(['a', 'b']), { flags: [], options: {}, positionals: ['a', 'b'] });

// value containing '=' splits only on the first
assert.deepStrictEqual(parseArgs(['--query=a=b']).options, { query: 'a=b' });

// -- terminator: everything after is positional
assert.deepStrictEqual(parseArgs(['--x', '--', '--not-a-flag', '--y=1']), {
  flags: ['x'],
  options: {},
  positionals: ['--not-a-flag', '--y=1'],
});

assert.deepStrictEqual(parseArgs([]), { flags: [], options: {}, positionals: [] });
console.log('PASS');

